import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root object
  const root = new Group();

  // Geometry: thin rule (adjust size as needed)
  const geometry = new PlaneGeometry(1.5, 0.05, 64, 64);

  // Material with PBR defaults
  const material = new MeshStandardNodeMaterial({
    color: (config.intent?.visualSpec?.colors?.paper) ?? '#e8ecf2',
    metalness: 0.3,
    roughness: 0.6,
    // subtle displacement
    displacementScale: 0.08,
  });

  // Load textures (async, but we return synchronously)
  const imagePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

  imagePromise.then((tex) => {
    material.mapNode = texture(tex);
    material.needsUpdate = true;
  });

  depthPromise.then((tex) => {
    material.displacementMapNode = texture(tex);
    material.needsUpdate = true;
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Apply any primitives declared in config
  const primitiveHandles = [];

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handle = ctx.primitives[prim.name](root, prim.params);
      primitiveHandles.push(handle);
    }
  }

  // Ensure parallax effect (required for render mode)
  const parallaxHandle = ctx.primitives['parallax-scroll'](root, {});
  primitiveHandles.push(parallaxHandle);

  // Event handlers
  const handlers = {};

  // Hover lift (rise‑in)
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(mesh.position, {
    y: mesh.position.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  });
  handlers.hover = () => hoverTL.restart();

  // Click press‑down + emit navigation event
  const clickTL = gsap.timeline({ paused: true });
  clickTL.to(mesh.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(1.7)',
  });
  handlers.click = () => {
    clickTL.restart();
    ctx.emit('hub-features.select', {});
  };

  root.userData.handlers = handlers;

  // Cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    hoverTL.kill();
    clickTL.kill();
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
  };

  return root;
}
